#if swift(>=5.8)
@_documentation(visibility: private)
#endif
nonisolated public struct FfiConverterTypeFfiLibrary: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = FfiLibrary

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> FfiLibrary {
        return FfiLibrary(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: FfiLibrary) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiLibrary {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: FfiLibrary, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
nonisolated public func FfiConverterTypeFfiLibrary_lift(_ pointer: UnsafeMutableRawPointer) throws -> FfiLibrary {
    return try FfiConverterTypeFfiLibrary.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
nonisolated public func FfiConverterTypeFfiLibrary_lower(_ value: FfiLibrary) -> UnsafeMutableRawPointer {
    return FfiConverterTypeFfiLibrary.lower(value)
}




nonisolated public struct FfiAlbum {
    public var albumId: String
    public var name: String
    public var parentAlbumId: String?
    public var mediaCount: UInt32
    public var deleted: Bool
    public var isDisconnected: Bool
    public var thumbnailMediaId: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(albumId: String, name: String, parentAlbumId: String?, mediaCount: UInt32, deleted: Bool, isDisconnected: Bool, thumbnailMediaId: String?) {
        self.albumId = albumId
        self.name = name
        self.parentAlbumId = parentAlbumId
        self.mediaCount = mediaCount
        self.deleted = deleted
        self.isDisconnected = isDisconnected
        self.thumbnailMediaId = thumbnailMediaId
    }
}

#if compiler(>=6)
nonisolated extension FfiAlbum: Sendable {}
#endif


nonisolated extension FfiAlbum: Equatable, Hashable {
    public static func ==(lhs: FfiAlbum, rhs: FfiAlbum) -> Bool {
        if lhs.albumId != rhs.albumId {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.parentAlbumId != rhs.parentAlbumId {
            return false
        }
        if lhs.mediaCount != rhs.mediaCount {
            return false
        }
        if lhs.deleted != rhs.deleted {
            return false
